-- ----------------------------
-- Table structure for accounts
-- ----------------------------
DROP TABLE IF EXISTS `accounts`;
CREATE TABLE `accounts`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(13) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `password` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `pin` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `pic` varchar(26) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `loggedin` tinyint NOT NULL DEFAULT 0,
  `lastlogin` timestamp NULL DEFAULT NULL,
  `createdat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `birthday` date NOT NULL DEFAULT '2005-05-11',
  `banned` tinyint(1) NOT NULL DEFAULT 0,
  `banreason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `macs` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `nxCredit` int NULL DEFAULT NULL,
  `maplePoint` int NULL DEFAULT NULL,
  `nxPrepaid` int NULL DEFAULT NULL,
  `characterslots` tinyint NOT NULL DEFAULT 3,
  `gender` tinyint NOT NULL DEFAULT 10,
  `tempban` timestamp NOT NULL DEFAULT '2005-05-11 00:00:00',
  `greason` tinyint NOT NULL DEFAULT 0,
  `tos` tinyint(1) NOT NULL DEFAULT 0,
  `sitelogged` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `webadmin` int NULL DEFAULT 0,
  `nick` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `mute` int NULL DEFAULT 0,
  `email` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `ip` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `rewardpoints` int NOT NULL DEFAULT 0,
  `votepoints` int NOT NULL DEFAULT 0,
  `hwid` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `language` int NOT NULL DEFAULT 3,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name` ASC) USING BTREE,
  INDEX `ranking1`(`id` ASC, `banned` ASC) USING BTREE,
  INDEX `id`(`id` ASC, `name` ASC) USING BTREE,
  INDEX `id_2`(`id` ASC, `nxCredit` ASC, `maplePoint` ASC, `nxPrepaid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of accounts
-- ----------------------------

-- ----------------------------
-- Table structure for activity_def
-- ----------------------------
DROP TABLE IF EXISTS `activity_def`;
CREATE TABLE `activity_def`  (
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动编码',
  `name_zh` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '中文名',
  `name_en` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '英文名',
  `category` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'TEAM/JUMP/QUIZ/TREASURE/MINIGAME/OTHER',
  `lobby_map_id` int NOT NULL COMMENT '报名/集合地图',
  `event_map_id` int NOT NULL COMMENT '开赛地图（可与lobby相同）',
  `related_maps` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '[]' COMMENT '相关地图JSON数组，清场/人数统计用',
  `team_event` tinyint NOT NULL DEFAULT 0 COMMENT '是否组队对抗',
  `supports_map_start` tinyint NOT NULL DEFAULT 0 COMMENT '是否支持MapleMap.startEvent',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序',
  `default_max_players` int NOT NULL DEFAULT 30 COMMENT '默认人数上限',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动目录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of activity_def
-- ----------------------------

-- ----------------------------
-- Table structure for activity_participant_result
-- ----------------------------
DROP TABLE IF EXISTS `activity_participant_result`;
CREATE TABLE `activity_participant_result`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `character_id` int NOT NULL,
  `character_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `team_id` int NULL DEFAULT NULL,
  `rank_no` int NULL DEFAULT NULL,
  `score` int NULL DEFAULT NULL,
  `finish_time_ms` bigint NULL DEFAULT NULL,
  `outcome` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'WIN/LOSE/DRAW/COMPLETE/ELIMINATED/PARTICIPATED',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '逗号标签 mvp,perfect',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_session_chr_result`(`session_id` ASC, `character_id` ASC) USING BTREE,
  INDEX `idx_result_session`(`session_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动场次成绩' ROW_FORMAT = Dynamic;

