-- ----------------------------
-- Table structure for activity_reward_claim
-- ----------------------------
DROP TABLE IF EXISTS `activity_reward_claim`;
CREATE TABLE `activity_reward_claim`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `tier_id` bigint NOT NULL,
  `tier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `character_id` int NOT NULL,
  `character_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `grant_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/CLAIMED/EXPIRED',
  `mesos` bigint NOT NULL DEFAULT 0,
  `exp` int NOT NULL DEFAULT 0,
  `item_id` int NOT NULL DEFAULT 0,
  `item_qty` int NOT NULL DEFAULT 0,
  `item2_id` int NOT NULL DEFAULT 0,
  `item2_qty` int NOT NULL DEFAULT 0,
  `announce_name` tinyint NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `claimed_at` datetime NULL DEFAULT NULL,
  `expire_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_claim_once`(`session_id` ASC, `tier_code` ASC, `character_id` ASC) USING BTREE,
  INDEX `idx_claim_chr_status`(`character_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动奖励领取单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of activity_reward_claim
-- ----------------------------

-- ----------------------------
-- Table structure for activity_reward_tier
-- ----------------------------
DROP TABLE IF EXISTS `activity_reward_tier`;
CREATE TABLE `activity_reward_tier`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `activity_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `tier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '档位编码，如同活动内唯一',
  `tier_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `priority` int NOT NULL DEFAULT 100 COMMENT '越小越先匹配；互斥组内只取最高优',
  `exclusive_group` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '互斥组，同组只发一档',
  `match_json` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '{}' COMMENT '条件JSON',
  `grant_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'CLAIM_NPC' COMMENT 'AUTO_BAG/AUTO_MAIL/CLAIM_NPC',
  `mesos` bigint NOT NULL DEFAULT 0,
  `exp` int NOT NULL DEFAULT 0,
  `item_id` int NOT NULL DEFAULT 0,
  `item_qty` int NOT NULL DEFAULT 0,
  `item2_id` int NOT NULL DEFAULT 0,
  `item2_qty` int NOT NULL DEFAULT 0,
  `announce_name` tinyint NOT NULL DEFAULT 0 COMMENT '是否全服公示名字',
  `announce_tpl` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '公示模板，{0}=名字 {1}=活动 {2}=档位',
  `enabled` tinyint NOT NULL DEFAULT 1,
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_activity_tier`(`activity_code` ASC, `tier_code` ASC) USING BTREE,
  INDEX `idx_reward_tier_code`(`activity_code` ASC, `enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动奖励档位' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of activity_reward_tier
-- ----------------------------

-- ----------------------------
-- Table structure for activity_schedule
-- ----------------------------
DROP TABLE IF EXISTS `activity_schedule`;
CREATE TABLE `activity_schedule`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `activity_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '活动编码',
  `world_id` int NOT NULL DEFAULT 0,
  `channel_id` int NOT NULL COMMENT '频道号，从1开始',
  `schedule_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ONCE/DAILY/WEEKLY',
  `start_at` datetime NULL DEFAULT NULL COMMENT 'ONCE：计划开始时间',
  `cron_time` time NULL DEFAULT NULL COMMENT 'DAILY/WEEKLY：每日时刻',
  `days_of_week` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'WEEKLY：1-7逗号分隔，1=周一',
  `max_players` int NOT NULL DEFAULT 30,
  `notify_minutes` int NOT NULL DEFAULT 30 COMMENT '开始前通知时长(分)',
  `notify_interval_sec` int NOT NULL DEFAULT 60 COMMENT '通知间隔(秒)',
  `prewarp_minutes` int NOT NULL DEFAULT 5 COMMENT '开始前自动传送(分)',
  `enabled` tinyint NOT NULL DEFAULT 1,
  `next_run_at` datetime NULL DEFAULT NULL COMMENT '下次执行时间（服务端维护）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_activity_schedule_next`(`enabled` ASC, `next_run_at` ASC) USING BTREE,
  INDEX `idx_activity_schedule_code`(`activity_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动排期' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of activity_schedule
-- ----------------------------

-- ----------------------------
-- Table structure for activity_session
-- ----------------------------
DROP TABLE IF EXISTS `activity_session`;
CREATE TABLE `activity_session`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `schedule_id` bigint NULL DEFAULT NULL COMMENT '来源排期，手动开为NULL',
  `activity_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `world_id` int NOT NULL DEFAULT 0,
  `channel_id` int NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'NOTIFYING/REGISTERING/PREWARP/RUNNING/STOPPED',
  `max_players` int NOT NULL DEFAULT 30,
  `planned_start_at` datetime NULL DEFAULT NULL,
  `opened_at` datetime NULL DEFAULT NULL,
  `started_at` datetime NULL DEFAULT NULL,
  `ended_at` datetime NULL DEFAULT NULL,
  `extra_info` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_activity_session_active`(`world_id` ASC, `channel_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_activity_session_code`(`activity_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活动场次' ROW_FORMAT = Dynamic;

