  INDEX `idx_char_item`(`characterid` ASC, `itemid` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '七彩棱镜染色记录' ROW_FORMAT = Dynamic;

