  `event_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '大区描述',
  `recommend_message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '大区推荐信息',
  `channel_size` int NULL DEFAULT NULL COMMENT '频道数',
  `exp_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '经验倍率',
  `meso_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '金币倍率',
  `drop_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '掉落倍率',
  `boss_drop_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT 'BOSS掉落倍率',
  `quest_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '任务倍率',
  `fishing_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '钓鱼倍率',
  `travel_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '旅行倍率',
  `level_exp_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '等级经验倍率，0为不启用',
  `quick_level` decimal(40, 3) NULL DEFAULT NULL COMMENT '冲刺等级，0为不启用',
  `quick_level_exp_rate` decimal(40, 3) NULL DEFAULT NULL COMMENT '冲刺等级经验倍率',
  `enabled` tinyint NULL DEFAULT 0 COMMENT '大区是否启用，0-不启用，1-启用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大区配置' ROW_FORMAT = Dynamic;

