-- ----------------------------
-- Table structure for xy_alchemy_tier
-- ----------------------------
DROP TABLE IF EXISTS `xy_alchemy_tier`;
CREATE TABLE `xy_alchemy_tier`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '副职业类型：1=炼金 2=炼药 3=锻造',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '品级名称（如：入门、普通、职业、大师、宗师）',
  `exp_start` bigint NOT NULL DEFAULT 0 COMMENT '达到该品级所需的最低累计经验（经验阈值）',
  `is_max` tinyint NOT NULL DEFAULT 0 COMMENT '是否为最高品级：0=否 1=是（最高品级无上限）',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '品级显示顺序，越小品级越低',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用：0=禁用 1=启用',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_sort_order`(`type` ASC, `sort_order` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '炼金师品级配置表（品级名称/经验阈值后台可配）' ROW_FORMAT = Dynamic;

