-- ----------------------------
-- Table structure for xy_cashshop_category
-- ----------------------------
DROP TABLE IF EXISTS `xy_cashshop_category`;
CREATE TABLE `xy_cashshop_category`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '显示名',
  `parent_id` int NULL DEFAULT NULL COMMENT '父分类，NULL=顶栏',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序，越小越靠前',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用 1/0',
  `click_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'SHOW_ITEMS' COMMENT 'SHOW_ITEMS|OPEN_WINDOW|SEND_PACKET|…',
  `click_param` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '窗口ID/协议载荷等',
  `gate_item_id` int NULL DEFAULT NULL COMMENT '持有该道具才可见，NULL=不限',
  `is_hot` tinyint NOT NULL DEFAULT 0 COMMENT '热卖榜类分类 1/0',
  `legacy_tab` int NULL DEFAULT NULL COMMENT '兼容现客户端 tab',
  `legacy_category` int NULL DEFAULT NULL COMMENT '兼容现客户端 category',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_sort`(`parent_id` ASC, `sort` ASC) USING BTREE,
  INDEX `idx_legacy`(`legacy_tab` ASC, `legacy_category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '窗口商城分类' ROW_FORMAT = Dynamic;

