-- Table structure for xy_cashshop_category_item
-- ----------------------------
DROP TABLE IF EXISTS `xy_cashshop_category_item`;
CREATE TABLE `xy_cashshop_category_item`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `category_id` int NOT NULL COMMENT '分类ID',
  `item_id` int NOT NULL COMMENT '物品ID',
  `sort` int NOT NULL DEFAULT 0 COMMENT '分类内排序',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '该分类下是否显示',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_cat_item`(`category_id` ASC, `item_id` ASC) USING BTREE,
  INDEX `idx_item`(`item_id` ASC) USING BTREE,
  CONSTRAINT `fk_xy_cs_ci_cat` FOREIGN KEY (`category_id`) REFERENCES `xy_cashshop_category` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_xy_cs_ci_item` FOREIGN KEY (`item_id`) REFERENCES `xy_cashshop_item` (`item_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 16868 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '窗口商城分类-商品关联（热卖可多挂）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_cashshop_category_item
