-- ----------------------------
-- Table structure for xy_cashshop_item
-- ----------------------------
DROP TABLE IF EXISTS `xy_cashshop_item`;
CREATE TABLE `xy_cashshop_item`  (
  `item_id` int NOT NULL COMMENT '物品ID（主键）',
  `price` int NOT NULL DEFAULT 0 COMMENT '点券价格',
  `count` int NOT NULL DEFAULT 1 COMMENT '数量',
  `period` int NOT NULL DEFAULT 0 COMMENT '有效期(天)，0=永久',
  `gender` int NOT NULL DEFAULT 0 COMMENT '性别 0双/1男/2女',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '展示名（可覆盖 String.wz）',
  `icon_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Web管理缩略图，游戏内仍读WZ',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '窗口商城商品主数据' ROW_FORMAT = Dynamic;

