-- Table structure for xy_character_challenge_fatigue
-- ----------------------------
DROP TABLE IF EXISTS `xy_character_challenge_fatigue`;
CREATE TABLE `xy_character_challenge_fatigue`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `character_id` int NOT NULL COMMENT '角色ID',
  `challenge_type` tinyint NOT NULL COMMENT '1=普通 2=进阶 3=团队',
  `remaining` int NOT NULL DEFAULT 3 COMMENT '剩余次数，当日可用恢复剂叠加',
  `last_reset_date` date NOT NULL COMMENT '上次跨天重置日期，跨天时重置为3',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_char_type`(`character_id` ASC, `challenge_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '角色挑战副本次数（按种类独立，跨天重置为3）' ROW_FORMAT = Dynamic;

