-- ----------------------------
-- Table structure for xy_character_challenge_log
-- ----------------------------
DROP TABLE IF EXISTS `xy_character_challenge_log`;
CREATE TABLE `xy_character_challenge_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `character_id` int NOT NULL COMMENT '角色ID',
  `account_id` int NOT NULL COMMENT '账号ID',
  `challenge_type` tinyint NOT NULL COMMENT '1=普通 2=进阶 3=团队',
  `action_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ENTER=进入挑战 RESTORE=使用恢复剂',
  `boss_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Boss名称（进入时）',
  `map_id` int NULL DEFAULT NULL COMMENT '地图ID',
  `mob_ids` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '怪物ID列表',
  `item_id` int NULL DEFAULT NULL COMMENT '恢复剂物品ID',
  `remaining_after` int NOT NULL COMMENT '操作后剩余次数',
  `create_time` datetime NOT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_time`(`character_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_type_time`(`challenge_type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_account_time`(`account_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '角色挑战副本操作日志' ROW_FORMAT = Dynamic;

