  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '配方名称(展示用，如：智慧戒指Ⅶ)',
  `tier_required` tinyint NOT NULL DEFAULT 0 COMMENT '所需锻造师品级下标：0=入门 1=普通 2=职业 3=大师 4=宗师',
  `result_item_id` int NOT NULL DEFAULT 0 COMMENT '打造产出装备ID（待定，占位）',
  `exp_gain` int NOT NULL DEFAULT 0 COMMENT '打造成功增加的锻造师经验',
  `meso_cost` bigint NOT NULL DEFAULT 0 COMMENT '打造消耗金币',
  `stamina_cost` int NOT NULL DEFAULT 0 COMMENT '打造消耗体力',
  `material1_item_id` int NULL DEFAULT NULL COMMENT '材料1物品ID（待定，占位，NULL表示不需要）',
  `material1_count` int NOT NULL DEFAULT 0 COMMENT '材料1所需数量',
  `material2_item_id` int NULL DEFAULT NULL COMMENT '材料2物品ID（待定，占位，NULL表示不需要）',
  `material2_count` int NOT NULL DEFAULT 0 COMMENT '材料2所需数量',
  `material3_item_id` int NULL DEFAULT NULL COMMENT '材料3物品ID（待定，占位，NULL表示不需要）',
  `material3_count` int NOT NULL DEFAULT 0 COMMENT '材料3所需数量',
  `str_min` int NOT NULL DEFAULT 0 COMMENT '力量默认随机区间下限(0表示该配方不涉及此属性)',
  `str_max` int NOT NULL DEFAULT 0 COMMENT '力量默认随机区间上限',
  `dex_min` int NOT NULL DEFAULT 0 COMMENT '敏捷默认随机区间下限(0表示该配方不涉及此属性)',
  `dex_max` int NOT NULL DEFAULT 0 COMMENT '敏捷默认随机区间上限',
  `int_min` int NOT NULL DEFAULT 0 COMMENT '智力默认随机区间下限(0表示该配方不涉及此属性)',
  `int_max` int NOT NULL DEFAULT 0 COMMENT '智力默认随机区间上限',
  `luk_min` int NOT NULL DEFAULT 0 COMMENT '运气默认随机区间下限(0表示该配方不涉及此属性)',
  `luk_max` int NOT NULL DEFAULT 0 COMMENT '运气默认随机区间上限',
  `watk_min` int NOT NULL DEFAULT 0 COMMENT '攻击力默认随机区间下限(0表示该配方不涉及此属性)',
  `watk_max` int NOT NULL DEFAULT 0 COMMENT '攻击力默认随机区间上限',
  `matk_min` int NOT NULL DEFAULT 0 COMMENT '魔攻默认随机区间下限(0表示该配方不涉及此属性)',
  `matk_max` int NOT NULL DEFAULT 0 COMMENT '魔攻默认随机区间上限',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '同品级内显示排序，越小越靠前',
  `enabled` tinyint NOT NULL DEFAULT 0 COMMENT '是否启用：0=禁用（待数据确定前默认禁用） 1=启用',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `material4_item_id` int NULL DEFAULT NULL COMMENT '材料4物品ID(NULL表示不需要)',
  `material4_count` int NOT NULL DEFAULT 0 COMMENT '材料4所需数量',
  `material5_item_id` int NULL DEFAULT NULL COMMENT '材料5物品ID(NULL表示不需要)',
  `material5_count` int NOT NULL DEFAULT 0 COMMENT '材料5所需数量',
  `material6_item_id` int NULL DEFAULT NULL COMMENT '材料6物品ID(NULL表示不需要)',
  `material6_count` int NOT NULL DEFAULT 0 COMMENT '材料6所需数量',
  `material7_item_id` int NULL DEFAULT NULL COMMENT '材料7物品ID(NULL表示不需要)',
  `material7_count` int NOT NULL DEFAULT 0 COMMENT '材料7所需数量',
  `material8_item_id` int NULL DEFAULT NULL COMMENT '材料8物品ID(NULL表示不需要)',
  `material8_count` int NOT NULL DEFAULT 0 COMMENT '材料8所需数量',
  `pdd_min` int NOT NULL DEFAULT 0 COMMENT '物理防御力默认随机区间下限(0表示不涉及)',
  `pdd_max` int NOT NULL DEFAULT 0 COMMENT '物理防御力默认随机区间上限',
  `mdd_min` int NOT NULL DEFAULT 0 COMMENT '魔法防御力默认随机区间下限(0表示不涉及)',
  `mdd_max` int NOT NULL DEFAULT 0 COMMENT '魔法防御力默认随机区间上限',
  `hp_min` int NOT NULL DEFAULT 0 COMMENT 'MaxHP默认随机区间下限(0表示不涉及)',
  `hp_max` int NOT NULL DEFAULT 0 COMMENT 'MaxHP默认随机区间上限',
  `mp_min` int NOT NULL DEFAULT 0 COMMENT 'MaxMP默认随机区间下限(0表示不涉及)',
  `mp_max` int NOT NULL DEFAULT 0 COMMENT 'MaxMP默认随机区间上限',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '打造配方配置表（打造物品/材料数据待定，默认禁用，正式数据确定后启用）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_forge_recipe
-- ----------------------------

-- ----------------------------
-- Table structure for xy_pet_growth_progress
-- ----------------------------
DROP TABLE IF EXISTS `xy_pet_growth_progress`;
CREATE TABLE `xy_pet_growth_progress`  (
  `petid` bigint NOT NULL COMMENT 'pets.petid',
  `growth_exp` int NOT NULL DEFAULT 0,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`petid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '宠物自定义成长经验进度' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_pet_growth_progress
-- ----------------------------

-- ----------------------------
-- Table structure for xy_pet_growth_stage
-- ----------------------------
DROP TABLE IF EXISTS `xy_pet_growth_stage`;
CREATE TABLE `xy_pet_growth_stage`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `chain_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '进阶链编码，同链多阶段共用',
  `stage` int NOT NULL DEFAULT 1 COMMENT '阶段序号，从1开始',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '展示名',
  `pet_id` int NOT NULL COMMENT '当前形态宠物物品ID(5000xxx)',
  `next_pet_id` int NULL DEFAULT NULL COMMENT '进阶目标宠物ID，空=终阶',
  `need_exp` int NOT NULL DEFAULT 100 COMMENT '本阶段进阶所需成长经验',
  `exp_per_feed` int NOT NULL DEFAULT 10 COMMENT '每次喂养增加成长经验',
  `feed_item_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '允许的喂养道具ID，逗号分隔；空=任意212宠物食品',
  `exp_rate` double NOT NULL DEFAULT 1 COMMENT '召唤时经验倍率（乘算）',
  `drop_rate` double NOT NULL DEFAULT 1 COMMENT '召唤时爆率倍率（乘算）',
  `meso_rate` double NOT NULL DEFAULT 1 COMMENT '召唤时金币倍率（乘算）',
  `sort_order` int NOT NULL DEFAULT 0,
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '0禁用 1启用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pet_growth_pet_id`(`pet_id` ASC) USING BTREE,
  INDEX `idx_pet_growth_chain`(`chain_code` ASC, `stage` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '宠物成长阶段配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_pet_growth_stage
-- ----------------------------

-- ----------------------------
-- Table structure for xy_reforge_affix
-- ----------------------------
DROP TABLE IF EXISTS `xy_reforge_affix`;
CREATE TABLE `xy_reforge_affix`  (
  `code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '词条代码：HP/DEF/WAR/MAG/BOW/THF/ALL/PAD/MAD/BRAVE/WISE/SWIFT/THORN/HOLY/XIAN/SHEN',
  `name_zh` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '中文名：血/防/战/法/弓/侠/全/攻/魔/勇/慧/迅/刺/圣/仙/神',
  `max_prefix` tinyint NOT NULL DEFAULT 5 COMMENT '最高前缀等级：血/防固定1，其余5',
  `base_json` json NOT NULL COMMENT '①级基值JSON：{\"HP\":100,\"MP\":100} 或 {\"STR\":2,\"DEX\":1} 等',
  `weight` int NOT NULL DEFAULT 10 COMMENT '抽取权重(万分比相对权重)，血/防低权重降低常驻概率',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用：0=禁用 1=启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '洗炼词条配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_reforge_affix
-- ----------------------------

-- ----------------------------
-- Table structure for xy_set_item
-- ----------------------------
DROP TABLE IF EXISTS `xy_set_item`;
CREATE TABLE `xy_set_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `set_id` int NOT NULL,
  `set_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `complete_count` int NOT NULL DEFAULT 0,
  `item_ids` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `enabled` int NOT NULL DEFAULT 1,
  `sort_order` int NOT NULL DEFAULT 0,
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `tiers_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_xy_set_item_set_id`(`set_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of xy_set_item
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
