INSERT INTO `lang_resources` VALUES (514, 'en-US', 'game_config', 'use_equipment_level_up_vicious', 'Equipment upgrade reduces vicious numbers', NULL);
INSERT INTO `lang_resources` VALUES (515, 'zh-CN', 'game_config', 'use_equipment_level_up_vicious_levelrange_chance', '装备升级减少金锤子次数的装备要求等级范围和概率。\n配置方法为数组，举例：\n配置两条概率判断，\n1、装备要求等级0~129，概率30%，\n2、装备要求等级130~255，概率90%\n配置如下：\n[[0,129,0.3],[130,255,0.9]]', NULL);
INSERT INTO `lang_resources` VALUES (516, 'en-US', 'game_config', 'use_equipment_level_up_vicious_levelrange_chance', 'Equipment upgrade reduces the required level range and probability of the Golden Hammer frequency.\r\nThe configuration method is an array, for example:\r\nConfigure two probability judgments,\r\n1. EquipRepLv 0~129, chance 30%,\r\n2. EquipRepLv 130-255, chance 90%\r\nThe configuration is as follows:\r\n[[0,129,0.3],[130,255,0.9]]', NULL);
INSERT INTO `lang_resources` VALUES (517, 'zh-CN', 'game_config', 'use_equipment_level_up_continuous', '是否允许装备连续升级', NULL);
INSERT INTO `lang_resources` VALUES (518, 'en_US', 'game_config', 'use_equipment_level_up_continuous', 'Do you allow continuous equipment upgrades', NULL);
INSERT INTO `lang_resources` VALUES (519, 'zh-CN', 'game_config', 'use_enable_party_level_limit_lift', '是否解除组队副本默认等级范围限制，开启时允许任意等级的玩家进入副本', NULL);
INSERT INTO `lang_resources` VALUES (520, 'en-US', 'game_config', 'use_enable_party_level_limit_lift', 'Should the default level range limit for teaming up dungeons be lifted, allowing players of any level to enter the dungeon when enableds', NULL);
